"""
agents/explanation_agent.py — Agent 7: Explanation Agent

Converts technical analysis results into plain language explanations
suitable for non-technical users.
"""
import logging
from .base import BaseAgent, AgentResult
from services.ai_provider import get_ai_provider

logger = logging.getLogger("agents.explanation_agent")

DISCLAIMER = (
    "[ADVISORY] This analysis is generated by AI and is advisory only. "
    "It should not be considered definitive proof that content is true, false, or malicious. "
    "Always verify important information through official sources."
)

CATEGORY_DESCRIPTIONS = {
    "fake_scholarship": "fake scholarship announcement",
    "fake_job": "fraudulent job advertisement",
    "investment_scam": "investment scam",
    "phishing": "phishing attempt",
    "prize_scam": "prize or lottery scam",
    "impersonation": "impersonation of a trusted entity",
    "payment_scam": "payment or fee scam",
    "scam": "scam",
    "fake_news": "potential misinformation",
    "health_misinfo": "health misinformation",
    "political_misinfo": "political misinformation",
    "fraud": "fraud",
    "suspicious_url": "suspicious website",
    "unknown": "unclassified suspicious content",
    "other": "suspicious content",
}


class ExplanationAgent(BaseAgent):
    """Agent 7 — Produces human-readable analysis explanations."""
    agent_name = "explanation"

    def analyze(
        self,
        risk_score: int = 0,
        risk_level: str = "needs_verification",
        threat_category: str = "unknown",
        confidence: int = 50,
        findings: list = None,
        recommendation: str = "",
        content_text: str = "",
        **kwargs,
    ) -> AgentResult:
        findings = findings or []
        ai = get_ai_provider()

        # Try AI-generated explanation first
        # generate_explanation returns a ProviderResponse dataclass
        ai_response = ai.generate_explanation(
            risk_score=risk_score,
            risk_level=risk_level,
            threat_category=threat_category,
            findings=findings,
            recommendation=recommendation,
        )

        if ai_response.success and ai_response.explanation:
            explanation = ai_response.explanation
        else:
            explanation = self._build_template_explanation(
                risk_score, risk_level, threat_category, confidence, findings, recommendation
            )

        summary = self._build_summary(risk_score, risk_level, threat_category)

        return AgentResult(
            success=True,
            agent_name=self.agent_name,
            score=risk_score,
            confidence=confidence,
            provider=ai_response.provider,
            findings=findings,
            data={
                "summary": summary,
                "explanation": explanation,
                "recommendation": recommendation,
                "disclaimer": DISCLAIMER,
            },
        )

    def _build_summary(self, score: int, risk_level: str, category: str) -> str:
        cat_desc = CATEGORY_DESCRIPTIONS.get(category, "suspicious content")
        level_map = {
            "trustworthy": "appears to be legitimate",
            "mostly_trustworthy": "appears mostly trustworthy",
            "needs_verification": "requires verification",
            "suspicious": "is suspicious",
            "high_risk": "is high risk",
            "scam": f"shows strong indicators of a {cat_desc}",
            "misinformation": "may contain misinformation",
        }
        verdict = level_map.get(risk_level, "requires careful review")
        return f"This content {verdict} (Risk Score: {score}/100)."

    def _build_template_explanation(
        self, score, risk_level, category, confidence, findings, recommendation
    ) -> str:
        cat_desc = CATEGORY_DESCRIPTIONS.get(category, "suspicious content")
        confidence_text = (
            "high" if confidence >= 70 else "moderate" if confidence >= 50 else "low"
        )

        if risk_level in ("trustworthy", "mostly_trustworthy"):
            intro = "[OK] This content appears to be legitimate based on our analysis."
        elif risk_level == "needs_verification":
            intro = "[WARNING] This content requires verification before you act on it."
        elif risk_level == "suspicious":
            intro = "[SUSPICIOUS] This content contains suspicious signals."
        else:
            intro = f"[ALERT] This content shows strong indicators of a {cat_desc}."

        lines = [intro, ""]
        if findings:
            lines.append("Why?")
            for f in findings[:6]:
                lines.append(f"- {f}")
            lines.append("")

        lines.append(f"AI Confidence: {confidence_text} ({confidence}%)")
        lines.append("")
        if recommendation:
            lines.append(f"Recommendation: {recommendation}")
        lines.append("")
        lines.append(DISCLAIMER)

        return "\n".join(lines)
